Plan:
- Read the cached values from the workbook and use the active sheet as the answer sheet.
- Count rows in the date/answer columns where the date matches the target date in row 1 and the answer matches the label in row 2.
- Write the four resulting counts as plain numbers into D3:G3.

```python
import shutil
import openpyxl
import datetime

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

answer_ws = wb.active
data_ws = wb["Sheet1"] if "Sheet1" in wb.sheetnames else answer_ws
vals_data = vals["Sheet1"] if "Sheet1" in vals.sheetnames else vals.active

def norm_date(v):
    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v
    if isinstance(v, str):
        s = v.strip()
        for fmt in ("%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d-%m-%Y", "%d/%m/%Y"):
            try:
                return datetime.datetime.strptime(s, fmt).date()
            except ValueError:
                pass
    return v

def count_label(target, label):
    if target is None or label is None:
        return 0
    label_s = str(label).strip()
    total = 0
    for row in vals_data.iter_rows(min_row=2, max_col=2):
        a = row[0].value
        b = row[1].value
        if a is None or b is None:
            continue
        if norm_date(a) == target and str(b).strip() == label_s:
            total += 1
    return total

specs = [
    ("D", "D", "Yes"),
    ("E", "D", "No"),
    ("F", "F", "Yes"),
    ("G", "F", "No"),
]

for col, target_col, default_label in specs:
    label = answer_ws[f"{col}2"].value
    if label is None:
        label = data_ws[f"{col}2"].value
    if label is None:
        label = default_label

    target = norm_date(answer_ws[f"{target_col}1"].value)
    if target is None:
        target = norm_date(data_ws[f"{target_col}1"].value)

    value = count_label(target, label)
    answer_ws[f"{col}3"] = value
    print(col, target, label, value)

wb.save(OUT)
